// Copyright (c) 2026 VEOR Browser Authors. All rights reserved.  #pragma once  #include <memory>  #include <autofill/IAutofillStore.h>  #include <infrastructure/crypto/ICryptoVault.h>  #include <infrastructure/storage/IStorageEngine.h>  namespace veor {  // ───────────────────────────────────────────────────────────────────────────── // AutofillStoreImpl // ───────────────────────────────────────────────────────────────────────────── // SQLite-backed autofill store with AES-256-GCM encryption for sensitive // fields (credit card numbers, CVV, passwords). // // Schema: //   autofill_profiles   (id, name_full, name_first, name_last, email, phone, //                          address_line1, address_line2, city, state, //                          postal_code, country, created_at, last_used) //   autofill_credit_cards (id, cardholder_name, number_encrypted, //                          expiry_month, expiry_year, cvv_encrypted, //                          created_at, last_used) //   autofill_passwords  (id, origin, username, password_encrypted, //                        created_at, last_used) // // Encryption key is derived from OS secure storage via CryptoVault. //  class AutofillStoreImpl : public IAutofillStore {  public:   AutofillStoreImpl(IStorageEngine* storage, ICryptoVault* crypto);   ~AutofillStoreImpl() override;    Result<std::vector<AutofillProfile>, std::string> GetProfiles() override;   Result<void, std::string> SaveProfile(const AutofillProfile& profile) override;   Result<void, std::string> DeleteProfile(int64_t id) override;    Result<std::vector<CreditCard>, std::string> GetCreditCards() override;   Result<void, std::string> SaveCreditCard(const CreditCard& card) override;   Result<void, std::string> DeleteCreditCard(int64_t id) override;    Result<std::vector<PasswordEntry>, std::string> GetPasswordsForOrigin(       const std::string& origin) override;   Result<void, std::string> SavePassword(const PasswordEntry& entry) override;   Result<void, std::string> DeletePassword(int64_t id) override;    Result<void, std::string> Initialize() override;  private:   std::vector<uint8_t> GetOrCreateEncryptionKey();   Result<std::string, std::string> EncryptField(const std::string& plaintext);   Result<std::string, std::string> DecryptField(const std::string& ciphertext);    IStorageEngine* storage_ = nullptr;   ICryptoVault* crypto_ = nullptr;   bool initialized_ = false; };  } // namespace veor